469	// cannot list files, and the whole enumeration for a materialized snapshot.
470	func walkSeedFiles(root string) ([]string, []string) {
471		var paths []string
472		var warnings []string
473		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
